import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// 1. Setup Scene
const scene = createScene();
scene.updateMatrixWorld(true);

const exportGroup = new THREE.Group();
const zUpMatrix = new THREE.Matrix4().makeRotationX(-Math.PI / 2);

// 2. Traverse and Bake
// We use a list to avoid issues if we modify the scene while traversing (though we are adding to exportGroup, not scene)
const meshes = [];

scene.traverse((object) => {
    if (object.isMesh) {
        meshes.push(object);
    }
});

meshes.forEach((object) => {
    if (object.isInstancedMesh) {
        const instanceCount = object.count;
        const originalGeometry = object.geometry;
        const meshMatrixWorld = object.matrixWorld;

        for (let i = 0; i < instanceCount; i++) {
            const instanceMatrix = new THREE.Matrix4();
            object.getMatrixAt(i, instanceMatrix);

            const finalMatrix = new THREE.Matrix4();
            finalMatrix.multiplyMatrices(meshMatrixWorld, instanceMatrix);

            const geom = originalGeometry.clone();
            geom.applyMatrix4(finalMatrix); // Bake instance + world
            geom.applyMatrix4(zUpMatrix);   // Convert to Z-up

            const mesh = new THREE.Mesh(geom);
            mesh.name = `${object.name}_${i}`;
            exportGroup.add(mesh);
        }
    } else {
        // Regular Mesh
        const geom = object.geometry.clone();
        geom.applyMatrix4(object.matrixWorld); // Bake world
        geom.applyMatrix4(zUpMatrix);          // Convert to Z-up

        const mesh = new THREE.Mesh(geom);
        mesh.name = object.name;
        exportGroup.add(mesh);
    }
});

// 3. Export
const exporter = new OBJExporter();
const result = exporter.parse(exportGroup);

// 4. Write
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)){
    fs.mkdirSync(outputDir, { recursive: true });
}
fs.writeFileSync(path.join(outputDir, 'object.obj'), result);
console.log('Export complete: /root/output/object.obj');

